import pathlib,json,html,re
base=pathlib.Path(__file__).parent
src=json.loads((base/'source.json').read_text(encoding='utf8'))
notes={i:{} for i in range(1,12)}
def add(s,r,meaning,status,action): notes[s][r]=(meaning,status,action)
def batch(s,rows,meaning,status,action):
    for r in rows: add(s,r,meaning,status,action)

# כל שורת מקור מקבלת הסבר, מצב בקוד ופעולה.
add(1,4,'כותרות: כמות מנות, חמישה סוגי שתייה, עמודת אחר, סיכום ללא מים וסודה וסיכום כולל. “מקס” הוא פפסי מקס.','C1/C8: אותם חמישה ענפים בקירוב; “מיץ” נקרא תפוזים/מים בטעמים. אין ענף אחר כללי.','לשמור את מיפוי המוצרים במזהים; לברר נפח בקבוק וגודל מארז. עמודת אחר ריקה ולכן אין נוסחה להעתיק ממנה.')
add(1,5,'70 הוא מספר המנות לדוגמה. כל שורות סוגי האירוע 6–9 הן חלופות המחושבות ממנו, לא סכומים שיש לצרף.','C1: guest_count הוא בסיס פעיל.','קלט אחד באירוע; להפעיל רק את מסלול האירוע הנבחר.')
add(1,6,'רגיל: פפסי/מקס/מיץ = 70÷9 = 7.777778 לכל סוג; מים וסודה = 70÷15 = 4.666667. סיכום ללא מים/סודה 23.333333; הכול 32.666667 לפני עיגול. לפי הצבעים ההזמנה 8+8+8+4+4=32.','C1 ובדיקה מבודדת: שלושת הראשונים מתאימים; מים וסודה מחושבים ÷9 ומעוגלים ל־7, במקום 4. הקוד מפצל את 8 יחידות המיץ ל־4 תפוזים ו־4 מים בטעמים.','לתקן את מחלק המים והסודה ל־15 בפרופיל רגיל; לשמור פיצול מיץ כאפשרות מפורשת שלא משנה סך. לחשב סך אחרי העיגול.')
add(1,7,'מתוק: כל חמשת הסוגים = 70÷15. ההזמנה לפי צבע 5,5,5,4,4 = 23. I7 ריק: אין סיכום ביניים ללא מים וסודה בשורה זו.','C1 ובדיקה: תואם את הכמות הכוללת לכל ענף; מיץ מתפצל 2+3.','לשמר יחס זה; לא להסיק מהתא הריק שאסור להציג סיכום ביניים במערכת.')
add(1,8,'שבת: שלושת הסוגים הראשונים = 70÷2÷4×2 = 17.5; מים וסודה = 70÷2÷5×2 = 14. סיכומים גולמיים 52.5 ו־80.5; הזמנה מעוגלת 82. המקדם 2 כתוב בנוסחה, אבל משמעותו התפעולית אינה מוסברת.','C1: הקוד משתמש ÷6 לרוב הסוגים ו־÷8 לסודה; התקבלו 12,12,12,11,8 = 55.','להגדיר כלל שבת נפרד לפי המקור לאחר אישור תחולה לכל השבת/סעודה; לא להניח שזו אותה הכפלה של מפות.')
add(1,9,'שבת מפוצל: שלושת הראשונים = 70÷2÷4×2.7 = 23.625; מים וסודה = 70÷2÷5×2.7 = 18.9. סיכום ביניים 70.875, הכול 108.675; הזמנה 108 לאחר עיגול הסוגים.','C1/C12: שדה פיצול בוקר קיים, אבל אינו משנה חישוב שתייה; התקבלה אותה תוצאה כמו שבת רגילה.','לחבר פיצול לפרופיל השתייה רק אחרי אימות שמשמעותו זהה למקור; לשמור 2.7 כמקדם נפרד.')
add(1,11,'מקרא הצבע הכתום: לעגל למעלה. הוא תואם לתאים C6:E9, כלומר פפסי, מקס ומיץ.','C1: ceil כבר מופעל על שלושת הענפים. צבעי המקור נבדקו בתצוגה.','לשמר את ההוראה כחוק מפורש; אין נוסחת ROUNDUP בתאי האקסל עצמם.')
add(1,12,'מקרא הצבע הירקרק: לעגל למטה. הוא תואם למים וסודה F6:G9.','C1: floor כבר מופעל על מים וסודה.','לשמר עיגול לפי סוג, לא לעגל את כל הבקבוקים באותה שיטה.')
add(1,16,'תא בודד C16 = 70×1.5 = 105. אין לו כותרת והוא אינו מפנה אל B5. הוא דומה לחישוב לחמניות, אך אין ראיה שמדובר דווקא בהן.','C1: קיים מקדם 1.5 ללחמניות רגילות, אבל התא הבלתי מתויג אינו קישור מוכח.','לשמור כפרט מקור לבירור, לא להוסיף 105 יחידות לשתייה ולא ליצור כלל חדש ממנו.')

add(2,2,'70 מנות הוא קלט לכל החלופות.','C2: מספר הסועדים קיים.','להשתמש באותו קלט של האירוע.')
for r,label,f,v in [(3,'רגיל','70÷8','8.75'),(4,'מתוק','70÷2÷8','4.375'),(5,'שבת','70÷8×2','17.5'),(6,'שבת מפוצל','70÷8×3','26.25')]:
    add(2,r,f'{label}: בסיס מפות {f} = {v}. התוצאה לפני עיגול ולפני ספייר; מקדם שבת מתייחס לכמות מפות ולא בהכרח למספר שולחנות פיזי.', 'C2/C12: הקוד מחלק לפי קיבולת צורה (8 או 12), מעגל ומוסיף 2; במתוק משתמש ב־60%. אין הכפלת שבת. במבחן 70 התקבלו 11 ברגיל/שבת/מפוצל ו־8 במתוק.', 'להפריד כמות שולחנות, מספר סבבי החלפת מפה, צורה ורזרבה. להשתמש בבסיס המקור ולבחור מלבן/מרובע בלי להחליף אוטומטית את המחלק 8.')
add(2,8,'הוראה מפורשת: להוסיף מפה אחת ספייר לכל 6 מפות. זהו רכיב נוסף לכמות הבסיס, שלא מופיע באף נוסחה בגיליון.','C2: קיימת תוספת קבועה של 2; היא אינה שקולה ליחס 1:6.','לברר קבוצה חלקית, סדר עיגול והאם הרזרבה על כלל השבת או כל סעודה. הצעה לאישור בלבד: base=ceil(raw), reserve=ceil(base/6). אז ל־70: רגיל 9+2=11, מתוק 5+1=6, שבת 18+3=21, מפוצל 27+5=32.')

add(3,2,'כותרת: חישוב מציות לשולחן מתוק. מציות הן מוצר פריך שמגישים כאן לצד הלחמניות; סוג/גודל החבילה שייך לקטלוג העסק.','C1–C3: אין ענף מציות ייעודי.','להוסיף חוק מותנה במתוק, בלי להפחית לחמניות על דעת עצמנו.')
add(3,3,'C3 מכיל נוסחה =250: זה מספר קבוע, לא חישוב תלוי תא.','C7: מספר מנות קיים באירוע.','להחליף בקלט האירוע; לא לקבע תמיד 250.')
add(3,4,'250÷2 = 125 מקומות ערוכים. חצי המנות הוא בסיס העריכה במתוק.','C2: בסיס שולחנות 60% וכלי עריכה על כל הסועדים; אין בסיס משותף של 50%.','להשתמש במספר המקומות הערוכים המתוקן, לא ליצור חצייה נוספת אחרי שכבר חושב.')
add(3,5,'125÷8 = 15.625 חבילות. כאן היחידה כתובה במפורש: חבילות, ולא מציות בודדות.','C3: אפשר לייצג בחוק מוצר, אבל אין חישוב מפורש שמופעל אוטומטית.','להוסיף מנות/16 חבילות לפני עיגול. אם נשלחות חבילות סגורות, הצעה לעגל ל־16, באישור. לא לחלק שוב בגודל חבילה אם הכמות כבר נמדדת בחבילות.')

add(4,2,'קלט 70 מנות; ארבעת סוגי האירוע הם חלופות.','C1: guest_count קיים.','לחבר לקלט המשותף.')
for r,label,formula,val,status in [(3,'רגיל','70×1.5','105','תואם במנוע'),(4,'מתוק','70÷2÷2×1.5','26.25','אותו יחס 0.375; המנוע מעגל למעלה ל־27'),(5,'שבת','70×1.6×2','224','לא תואם; המנוע נותן 105'),(6,'שבת מפוצל','70×1.6×3','336','לא תואם; המנוע נותן 105 גם כשהפיצול מופעל')]:
    add(4,r,f'{label}: {formula} = {val} לחמניות. במתוק שתי חלוקות ב־2; הסיבה העסקית לחלוקה השנייה אינה מוסברת בגיליון, ולכן שומרים את הנוסחה בלי להמציא נימוק.',f'C1/C12: {status}. חלוקת לחמניות לסוגים כבר קיימת ומחלקת סכום שלם.', 'לשמר רגיל ומתוק, להוסיף את שני מסלולי שבת ולאשר עיגול/גודל מארז. חלוקה לסוגי לחמניות תיעשה אחרי חישוב הסך בלי להגדיל אותו.')

add(5,2,'250 מנות הוא בסיס התפריט. אין פירושו 250 יחידות מכל מנה.','C3: הכמות קיימת, אך המנוע משתמש במשקלים אחרים.','קלט אירוע אחד; שיוך החוקים למזהי המנות ולא לחיפוש בשם.')
add(5,4,'C = מנות לחישוב; D = מנות להזמנה. אלה שני דברים שונים, במיוחד בלינצ׳ס וסיגרים.','C3: יש equivalent_quantity וכמות הזמנה, אך עם נוסחאות אחרות.','להציג בנפרד יחידות/מנות שקולות ורכישות; לא לסכום שתי עמודות כאילו הן אותו מדד.')
hot={5:('בלינצעס','C5=250/3=83.333333; D5=C5+C16=166.666667. הבלינצ׳ס מופיעים בשני שלבים ומוזמנים יחד.','במנוע משקל 1.7/3 וחישוב תוספת “ראשונות פחות מנות”, לא סכום השורות שבאקסל.'),6:('טורטיות','250/3=83.333333; אותה כמות עוברת להזמנה.','במנוע משקל 1.5/3 וחלוקה מחדש.'),7:('פילו ירקות','250/3=83.333333; אותה כמות עוברת להזמנה.','פילו אינו בטבלת זיהוי המנות של המנוע.'),9:('נודלס','250/6×2=83.333333 לחישוב ולהזמנה.','משקל בסיס 2/6 קיים, אבל חלוקה מחדש לפי הבחירות משנה את התוצאה.'),10:('אורז','250/6×2=83.333333 לחישוב ולהזמנה.','משקל בסיס 2/6 קיים, אבל חלוקה מחדש משנה אותו.'),11:('קוגל איטריות','250/6×2=83.333333. קוגל הוא מאפה שמחלקים למנות; המקור אינו נותן משקל או גודל תבנית.','במנוע 3/6 במקום 2/6 וזיהוי איות בשם.'),12:('קוגל תפוחי אדמה','250/6×2=83.333333. זהו פריט נפרד מקוגל איטריות.','במנוע 3/6 במקום 2/6.'),13:('סיגרים','C13 הוא אפס קבוע; D13=250/2=125 להזמנה. סיגרים הם מאפים מגולגלים, אך גודל היחידה אינו מוגדר.','במנוע 2.5/6, חלוקה מחדש וחלוקה נוספת ב־1.5 — נוסחה אחרת.'),14:('פשטידות','C14=0 קבוע ו־D14 מפנה אליו. כרגע אין כמות, אף שהשורה כלולה בסיכום C17.','במנוע משקל 2.5/6 בעת בחירת פשטידה; אינו משקף את האפס שבמקור.'),15:('צ׳ולנט / תפוחי אדמה פיקנטי','250/6×2=83.333333; הכותרת מציעה חלופות. צ׳ולנט הוא תבשיל חמין.','לצולנט משקל בסיס 2/6 וזיהוי בשם; אין חלופה מובנית לפיקנטי בטבלת המנוע.'),16:('בלינצע׳ס','250/6×2=83.333333 נוסף לחישוב; D16 ריק מפני שהסכום כבר הועבר אל D5.','המנוע לא מחבר את שורת הבסיס הזו ל־D5 באותה דרך.')}
for r,(name,ex,st) in hot.items():
    action='להגדיר חוק לפי המנה והשלב, לשמור מקור ולאשר עיגול ליחידות. אין הוראה באקסל לחלק אוטומטית את הכמות של מנה שלא נבחרה בין אחרות.'
    if r==13: action='לברר למה 125 להזמנה מול אפס במנות והיעדר בסיכום. לא לתקן ל־125 מנות שקולות בלי אישור.'
    if r==14: action='לשמור כפריט אופציונלי; לברר יחס אם מפעילים. אפס במקור אינו הוכחה שצריך למחוק את הפשטידה.'
    if r==16: action='לחבר פעם אחת לבלינצ׳ס להזמנה; לא להזמין D5 ועוד C16 ולספור שוב את החלק הזה.'
    add(5,r,name+': '+ex,'C3: '+st,action)
add(5,8,'C8 מחבר C5+C6+C7 = 250 מנות ראשונות. אין סך הזמנה בעמודה D בשורה הזו.','C3: סכום משקלי קבוצת הראשונות הקיימת הוא 1.233333 לסועד לפני השפעת כמויות; זו קבוצה אחרת הכוללת פלפל במקום פילו.','לחשב סיכום לפי אותן שורות מאושרות; תוצאה 250 בדוגמת המקור.')
add(5,17,'C17 מחבר C16,C15,C14,C12,C11,C10,C9 = 500. הכותרת “אחרונות” כאן מתייחסת לחלק החם הנוסף בטבלה, ולא לגיליון קינוחים. C13 של סיגרים אינו מופיע בנוסחה.','C3: קבוצת hot במנוע כוללת משקלים אחרים; אין שחזור של סכום המקור.','לסמן את השמטת C13 לבירור; גם אם ישנו אותו מאפס, הסיכום לא יתעדכן. לא להסתמך על 500 כסך ההזמנה.')
add(5,18,'250+500 = 750 מנות חישוביות. סכום שורות ההזמנה D5:D15 הוא 875; הפער 125 הוא הסיגרים.','C3: המנוע אינו מבצע ביקורת בין שני המדדים האלה.','להציג שתי יחידות ברורות וסיבת פער, או לתקן סכום לאחר אישור הבעלים. זו אי־התאמה סמנטית גם כשהנוסחה תקינה.')
add(5,19,'750÷250 = 3 מנות חישוביות לאדם. זה לא מוכיח ששלוש יחידות פיזיות בלבד נשלחות לאדם; סכום D הוא 3.5 לסועד בדוגמה.','C3: לא נמצא אותו מדד מסכם.','להוסיף סיכום בקרה רק אחרי הגדרת היחס בין “מנה” ליחידת הזמנה. להגן על חלוקה באפס.')

# שתי טבלאות הכלים: כל שורה נבדקת בנפרד, גם כשהתוכן דומה.
tool_status='C4/C7/C8/C10: קיימת תשתית סטים ובחירת סט לאירוע; לא אומת שהרשומה הספציפית הוזנה לקטלוג העסק. C9: מסמכי המלצר והסיכום קוראים עדיין את רשימת הכלים הישנה.'
tool_action='להגדיר פריטי סט במנה הקיימת, עם מזהי כלים; בסיס אישי לפי מקבלי המנה ומרכזי לפי קבוצות עריכה של שמונה. לחבר גם לחישוב וגם למסמך, בלי להוסיף במקביל את הסט הישן.'
batch(6,[1,5],'סידור לפי דף האירוע: מזרח, מרובעים, ח׳ וכדומה. מפה מרובעת לשולחן מרובע/רחב, מלבן לצר/ארוך; במזרח בדרך כלל מלבן. בשורה 1 יש גם הוראה ב־AA1, רחוק מהטבלה הראשית — היא נכללה בבדיקה.','C2: צורה אחת בהגדרות, בלי מימוש חלוקה מעורבת לפי table_overrides.','להוסיף חלוקה לפי צורה/אזור באותו אירוע; לשמור את “בדרך כלל” כהמלצה הניתנת לשינוי, לא כלל קשיח.')
add(7,2,'אותן הוראות סידור ומפות, במסלול כלים אמיתיים.','C2: צורה אחת; אין שימוש חישובי ב־table_overrides.','אותה חלוקת שולחנות משותפת לשני מסלולי הכלים; לא להעתיק אירוע נוסף.')
for s,r in [(6,7),(7,4)]: add(s,r,'הוראה מספרית מפורשת: הגשה מרכזית לפי הכמות הכוללת של העריכה חלקי 8. לכן ב־70 רגיל הבסיס 8.75, ובמתוק שחצי ממנו ערוך — 4.375.','C2/C4: בסיס table קיים אך מבוסס על קיבולת צורה, 60% במתוק ועיגול מוקדם.','להגדיר בסיס קבוצות הגשה נפרד. כלי שלם יצריך עיגול מאושר; מספר קערות למזון לא חייב להיות מעוגל מראש. לברר חריגים לכלי קינוח/פריטי מרכז.')
for s,r in [(6,8),(7,5)]: add(s,r,'לכל מקום רגיל: צלחת קטנה יפה + גדולה יפה + כוס יפה + מפית מדוגמת + שני סכינים ושני מזלגות יפים. מלחיה וברכונים במרכז. אין כמות מפורשת של ברכונים/מלחיות.','C2/C8: סט אירוע לפי כמות לסועד יכול לייצג 1/1/1/1/2/2, אבל צריך נתוני קטלוג; לא הוכח שברירת המחדל הנכונה קיימת.','לבנות תבנית עריכה מהכלים הקיימים; מרכזיים לחשב בנפרד ורק עם כמות מאושרת. לשמור הבחנה יפה/פשוט.')
for s,r in [(6,9),(7,6)]: add(s,r,'מתוק: עורכים חצי מכמות המנות. לכל מקום צלחת קטנה יפה, כוס יפה, מפית, סכין ומזלג יפים; אין צלחת גדולה ברשימה. מלחיה וברכונים במרכז.','C2: כלי האירוע מחושבים כיום על כל הסועדים; בסיס השולחנות 60%, שניהם אינם ברירת המחדל המבוקשת.','להכפיל במספר הערוכים, לא בכל הסועדים; לא לכלול צלחת גדולה מתבנית רגילה. לאשר עיגול כשמספר המנות אי־זוגי.')
for s,r in [(6,11),(7,8)]: add(s,r,'מנות נוספות במתוק, צלחת שהתבקשה בנוסף, שבר או אורחים נוספים — משתמשים בסוג הפשוט. אין כאן כמות רזרבה מספרית.','C7/C8: כלים ידניים וסוגי כלים קיימים; אין כלל כמות מאושר לכל המצבים.','לשמור הוראת מלצר ולספק הגדרת ספייר נפרדת. אין להמציא אחוז תוספת מהטקסט.')
items={13:('לחמניות','קערה משותפת ללחמניות. לא צוין כלי חלוקה נלווה.'),14:('מציות','קסרול שקוף; אין סכו״ם כתוב.'),17:('כרוב','תערובת כרוב לבן וסגול, בצל ירוק, רוטב וחלופה געלה/חמניה פיקנטי/פקאן; כף יפה וקערה גלאס.'),18:('חסה','חסה, שרי, פטריות, נבטים, בצל סגול, רוטב, נשנושים/פקאן; כף יפה וקערה שקופה עגולה גדולה.'),19:('חציל סירות','חציל עם טחינה, פטרוזיליה וצנוברים; צלחת גדולה מסוג העריכה וסכין ומזלג יפים. כלי ההגשה מתווסף לכלי העריכה האישיים.'),20:('חומוס','חומוס ומעליו גרגרים, שמן זית/בצל/סחוג/פטרוזיליה; צלחת קטנה מסוג העריכה וכפית יפה. לשמר חלופות ולא להוסיף את כולן אוטומטית.'),21:('גזר / חמוצים / שרי','חלופות סלט; מרקית מסט העריכה וכפית יפה. אזכור קופסה מוכנה אינו מתכון לחומרי גלם.'),22:('בטטה / סלט נוסף','קסרול מסט העריכה וכפית יפה. נשים? מתנה? נכתבו כסימני שאלה ואינם דרישה מוכרעת.'),26:('מרק כתום וקרוטונים','מרקית אישית וכף יפה אישית לכל מקבל מרק; קסרול מרכזי לקרוטונים וכפית יפה לקרוטונים. שני בסיסי כמות באותו סט.'),27:('טורטיות עם צ׳ילי — אישי','צלחת שקופה פשוטה ומזלג פשוט לכל מקבל; צ׳ילי הוא רכיב אריזה נפרד אם נשלח להרכבה.'),28:('בלינצעס עם רוטב — אישי','צלחת שקופה פשוטה ומזלג פשוט; הרוטב אינו כלי וצריך להופיע במוצרים/אריזה.'),29:('פלפל — אישי','צלחת שקופה פשוטה ומזלג פשוט. המקור אינו מפרט כאן מילוי או כמות אוכל.'),30:('פילו ירקות — אישי','צלחת שקופה פשוטה ומזלג פשוט.'),31:('טורטיות עם צ׳ילי — מרכזי','אובל נמוך וכף יפה. זו חלופת הגשה של אותה מנה, לא מנה נוספת.'),32:('בלינצעס עם רוטב — מרכזי','אובל נמוך וכף יפה, והרוטב במוצרי ההגשה.'),33:('פלפל — מרכזי','אובל עמוק וכף יפה; אין להחליף באובל הנמוך של הטורטיות.'),34:('פילו ירקות — מרכזי','אובל נמוך וכף יפה.'),38:('שניצל — אישי','כתוב “הגשה אישית” בלבד; לא מפורטים כלי או סכו״ם.'),39:('עוף — אישי','כתוב “הגשה אישית” בלבד; אין פירוט כלי.'),40:('סלומון — אישי','הכוונה לשם דג סלמון, כפי שנכתב במקור; כלי וסכו״ם חסרים.'),41:('שניצל — מרכזי','אובל נמוך וכף יפה.'),42:('עוף — מרכזי','אובל עמוק וכף יפה.'),43:('סלומון — מרכזי','אובל עמוק וכף יפה.'),47:('אורז ותוספת','קערת כלנית וכף יפה; התוספת היא מזון שיש לחשב בנפרד אם אינו כלול במוצר המוכן.'),48:('תפוחי אדמה','קערת כלנית וכף יפה.'),49:('שעועית','מרקית מסט העריכה וכף יפה; שומשום ושקדים נלווים.'),50:('פסטה','קערת כלנית וכף יפה.'),51:('קוגל — שורה ראשונה','אובל עמוק וכף יפה; סוג הקוגל לא נכתב.'),52:('קוגל — שורה שנייה','שורה נפרדת עם אותם כלים. אין להניח שזו כפילות למחיקה; ייתכן סוג אחר, אך זו השערה.'),53:('סיגרים','אובל נמוך וכף יפה.'),54:('פשטידות','אובל נמוך וכף יפה.'),55:('צונט','קערה שקופה כפולה — שתי קערות זו בתוך זו לפי נוסח ההגשה שבדרישות. אין סכו״ם רשום בתא.'),59:('מיקס קינוחים','כפית, ובחירה בין הגשה אישית / אובל גדול / מגש זהב. אין כמות קינוחים או יחס כלים מפורט בשורה.')}
real_replacements={17:'קערה לכרוב במקום קערה גלאס.',18:'קערה לחסה במקום קערה שקופה עגולה גדולה.',19:'צלחת לחציל סירות במקום תיאור צלחת גדולה מהסט.',20:'צלחת חומוס במקום תיאור צלחת קטנה מהסט.',21:'מרקית לסלט במקום מרקית מהסט.',22:'קסרול לסלט במקום קסרול מהסט.',27:'כתוב צלחת פשוטה; המילה שקופה אינה מופיעה.',28:'כתוב צלחת פשוטה; המילה שקופה אינה מופיעה.',29:'כתוב צלחת פשוטה; המילה שקופה אינה מופיעה.',30:'כתוב צלחת פשוטה; המילה שקופה אינה מופיעה.',47:'קערה לאורז במקום קערת כלנית.',48:'קערה לתפוחי אדמה במקום קערת כלנית.',49:'מרקית או קערה דומה לשעועית — חלופה, לא שני כלים.',50:'קערה לפסטה במקום קערת כלנית.',55:'קערה לצ׳ונט; בגיליון זה לא כתוב כפולה. אין להעתיק אליו אוטומטית את המקדם 2.'}
for r,(name,ex) in items.items():
    action=tool_action
    if r in (38,39,40): action='לשמור חלופת הגשה עם חוסר נתון מסומן; לקבל מבעל העסק כלי וסכו״ם לפני הפעלת סט אוטומטי. אין להסיק שאין צורך בכלי.'
    if r in (51,52): action+=' לברר את שני סוגי הקוגל ולשמור שתי שורות מקור עד להכרעה.'
    if r==22: action+=' את תנאי הנשים/מתנה להשאיר לא מאושר; מתנה אינה פוטרת מאריזה.'
    add(6,r,name+': '+ex,tool_status,action)
    realex=ex
    if r in real_replacements: realex='התפקיד והרכיבים כמו בשורה המקבילה בגיליון כלים. ההבדל המדויק: '+real_replacements[r]
    add(7,r-2,name+': '+realex,tool_status+' סוג כלי רב־פעמי ושריון קיימים, אך אינם הוכחה להתאמת הסט לגיליון.',action+' לבחור את מזהי הכלים במסלול האמיתי; לא לספור יחד את שני הגיליונות.')

add(8,2,'כותרת תוספות ומספר שולחנות–קערות. החישוב עוסק ברכיבים קטנים שמרכיבים בהגשה.','C3: salad_garnish הוא המנגנון המתאים.','להרחיב אותו, לא ליצור טבלת מלאי תוספות נפרדת.')
for r in (3,16): add(8,r,'250 מנות; רגיל 250÷8=31.25 קבוצות קערה; מתוק 250÷2÷8=15.625. שורה 16 היא קלט נפרד לרטבים — שינוי D3 לבדו לא משנה את D16.','C2/C3: המנוע משתמש בשולחנות מעוגלים ו־60% למתוק; בדיקה נתנה 32/19 במקום הבסיס שבמקור.','קלט אירוע משותף לתוספות ולרטבים, עם אפשרות חריגה מתועדת אם נחוצה. לא לעגל מוקדם את בסיס המזון.')
for r in (4,17): add(8,r,'עמודות: תוספת, לאיזו מנה, כמות מספרית לקערה, הסבר יחידה, סך לאריזה רגיל וסך מתוק. F ו־H הם כמות לשליחה; אין כאן קיזוז מלאי.','C3/C6: חוק כמות לקערה קיים; צריך להבחין בין דרישה למלאי ולהמיר יחידות לפני קיזוז.','להציג יחידה מחייבת, לבחור מנה/חלופה ולהוסיף לאריזה גם אם הכול כבר במלאי.')
garnishes={5:('פקאן','חסה או כרוב',60,'גרם'),6:('געלה','כרוב',55,'גרם'),7:('חמוציות ושקדים','כרוב',35,'גרם'),8:('שקדים מולבנים','שרי',25,'גרם'),9:('שקדים ושומשום','שעועית מוקפצת',25,'גרם'),10:('מנצס','כרוב או גזר',12,'גרם'),11:('צנוברים','חציל סירות',6,'גרם'),12:('תערובת שקדים חמוציות וסילאן','אורז',50,'גרם'),18:('רוטב חסה הדרים','חסה',70,'מ״ל'),19:('רוטב כרוב סויה','מיקס כרובים',50,'מ״ל'),20:('רוטב חסה מיונז','חסה שבת',70,'מ״ל')}
for r,(name,dish,q,unit) in garnishes.items():
    add(8,r,f'{name} עבור {dish}: {q} {unit} לקערה חישובית. ל־250 מנות רגיל: {q}×31.25={q*31.25:g} {unit}; מתוק: {q}×15.625={q*15.625:g} {unit}. תערובת נחשבת מוצר אחד בשורה; אין פירוט יחס רכיביה.', 'C3: ניתן לייצג ב־salad_garnish; הכמות הנוכחית תהיה שונה בגלל בסיס הקערות. לא אומתה הגדרת מוצר זה במסד. C6: דרישות מחושבות אינן מומרות ליחידת המלאי לפני קיזוז.', 'לשמור חוק בכמות וביחידה הנתונות, לבחור את התוספת המתאימה למנה, ולהמיר גרם/ק״ג או מ״ל/ליטר. לא להפעיל את כל חלופות הכרוב/חסה יחד. רוטב מיונז לחסה שבת צריך תנאי מתאים, לא כל חסה.')
add(8,13,'נשנושים לחסה: D13=0.05; ההסבר E13 אומר “1 חבילה”. הנוסחה נותנת 1.5625 ברגיל ו־0.78125 במתוק, אבל היחידה אינה מוכרעת בגלל הסתירה.','C3: בלי unit החוק נופל כברירת מחדל לגרם; זו תהיה פרשנות לא מבוססת של המספר.','לבקש יחידת 0.05 וגודל החבילה. עד אז שורה מסומנת “חסר נתון”, לא חוסר של אפס ולא הזמנה אוטומטית.')
add(8,15,'כותרת מספר שולחנות–קערות של חלק הרטבים.','C3: אין צורך במנגנון אחר לרטבים.','להשתמש באותו בסיס ובאותו שירות, עם יחידת נפח.')

add(9,6,'עמודות: סכום בסיס, מספר תשלומים, עמלה באחוזים, מכפיל המכונה מע״מ, תוספת וסכום כולל. D7=1.18 הוא מכפיל, לא 1.18%.','C5/C7: יש הפעלת אשראי וסכום אשראי; אין מספר תשלומים או טבלת אחוזים.','להוסיף בחירת מסלול לאחר הכרעה מול המייל; לשמור שיעור, מכפיל, בסיס וסכום באירוע המאושר.')
for r,n,rate in [(7,1,1.9),(8,2,2.36),(9,3,2.74),(10,4,3.12),(11,5,3.49),(12,6,3.87)]:
    fee=rate*1.18
    add(9,r,f'{n} תשלומים: בסיס A7=100, עמלה {rate}% ומכפיל D7=1.18. תוספת = 100×{rate}×1.18÷100 = {fee:.4f}; כולל {100+fee:.4f}. כל השורות מפנות לאותו A7 ולאותו D7; הריקים ב־A/D אינם אפסים.','C5: נוסחת תשלום אחד קיימת, כולל עיגול לשתי ספרות; יתר המסלולים לא קיימים. 3/6 שונים מהדרישה המתועדת מהמייל.' if n!=1 else 'C5: אותו שיעור קיים; הקוד מעגל 2.242 ל־2.24 על בסיס 100. בחירת בסיס החיוב עדיין דורשת איחוד בין שני השירותים.','להשתמש בטבלת תעריפים מאושרת. לא לטעון שזו עלות סליקה עדכנית או דין מס; אלה מספרי המקור. לעגל אגורות פעם אחת ולא לחייב עמלה על עמלה.')

add(10,3,'תשעה חומרי גלם לסלטים: אייסברג, חסה רגילה, כרוב סגול ולבן, שרי, בצל ירוק, פטרוזיליה, פטריות ונבטים עבים. היחידות אינן כתובות.','C6: מוצר/רכיב מתכון וחוק מוצר קיימים, אך אין מימוש ייעודי לטבלה.','לשייך למתכוני/הכנת סלטים. לא להפעיל את כל הירקות לכל אירוע או לחוסרי סלט מוכן.')
add(10,4,'70 הוא בסיס המנות.','guest_count קיים.','לבסס על סועדים המקבלים את הסלט; לברר אם כל האירוע מקבל כל אחד מהסלטים.')
for r,mode,scale in [(5,'רגיל',1),(6,'מתוק',.5)]:
    terms=[('אייסברג',30),('חסה רגילה',10),('כרוב סגול',75),('כרוב לבן',37),('שרי',60),('בצל ירוק',30),('פטרוזיליה',60),('פטריות',40),('נבטים עבים',30)]
    ex='; '.join(f'{name}: 70'+('÷2' if scale==.5 else '')+f'÷{den}={70*scale/den:.6g}' for name,den in terms)
    add(10,r,f'{mode}: '+ex+'. כל תוצאה ביחידה שטרם צוינה; אין לחבר אותן לסך אחד. חסה רגילה ואייסברג עשויים להיות חלופות — לא ניתן להכריע מהנוסחאות בלבד.', 'C3/C6: custom_product מאפשר מקדם לאורח, אבל אינו מחיל כאן אוטומטית חצי במתוק או בחירת הסלט. בנתיב רכיבים יש המרות; ביחידות לא ידועות אי אפשר להשלים התאמה.', 'להגדיר לכל אחד מתשעת המוצרים יחידה, יחס ותנאי שימוש. לשמר מחלק 37 לכרוב לבן — לא “לתקן” ל־37.5 או לעגל בלי אישור. לתכנן מזון מוכן בנפרד מחומרי מטבח.')

add(11,2,'הוראת מפתח “ליטר ל־3 שולחנות”; 70 מנות. אין שם סלט. הכוונה לכמות נפח לשליחה, ולא לכמות הירקות להכנה.','C3/C6: אין חוק ייעודי למשלוח סלט בליטרים; אפשר להרחיב חוק מוצר קיים.','לברר לאילו סלטים חל הכלל והאם לכל סוג בנפרד. לשייך למוצר סלט מוכן ולא לחומרי הגלם אוטומטית.')
add(11,3,'רגיל: D3=70÷8=8.75 שולחנות חישוביים; C3=8.75÷3=2.916667 ליטר. כלומר מנות÷24.','C3: אין כלל פעיל ייעודי; בסיס table הקיים יעגל ל־9 לפני חלוקה וייתן 3, שאינו חישוב האקסל המדויק.','לחשב נפח לפני עיגול, ואחר כך לבחור מכלי אריזה וקיבולתם. לא לקנות “3 חבילות” בלי לדעת נפח חבילה.')
add(11,4,'מתוק: D4=70÷8÷2=4.375; C4=1.458333 ליטר. כלומר מנות÷48.','C2/C3: חצי עריכה אינו הבסיס הקיים; אין כלל ייעודי.','להחיל חצי פעם אחת בלבד ולשמור תוצאת נפח, לא מספר קערות שלם.')
add(11,6,'כותרת “סלט לנשים בלבד”. זה קהל יעד נפרד, אבל לא שם סלט ולא הוראה להפעילו בכל אירוע.','Event אינו כולל בשדות שנקראו מספר נשים ייעודי; אין קהל יעד כזה בחוקי החישוב.','להוסיף קהל יעד מוגדר באותו מנגנון; לא לזהות נשים מתוך שם המנה או להפעיל מתנה אוטומטית.')
add(11,7,'קלט נפרד 250 מנות לחלק נשים; אינו מפנה ל־C2=70 שבחלק העליון.','המערכת משתמשת במספר מנות האירוע; אין בסיס מקור נפרד לנשים.','לאחד לקלט האירוע ולהגדיר בנפרד מספר נשים; לא להעתיק 250 כברירת מחדל.')
add(11,8,'רגיל נשים: D8=250÷8÷2=15.625; C8=5.208333 ליטר. המקור מניח 50% נשים: 125÷24.','C3/C7: אין כלל קהל יעד פעיל; מקדם קבוע בחוק כללי אפשרי אבל לא מייצג מספר נשים אמיתי.','לשמר את 50% כהנחת מקור ברורה הניתנת לאישור/שינוי; אם הוזן מספר נשים, לחשב ממנו ולא לחצות שוב.')
add(11,9,'מתוק נשים: D9=250÷8÷2÷2=7.8125; C9=2.604167 ליטר. חצי אחד לנשים וחצי לעריכה במתוק.','C3/C7: אין חישוב ייעודי לשילוב שני התנאים.','להפריד את שני הגורמים כדי שלא יחולו פעמיים. לברר אם שיעור העריכה של הנשים זהה לשיעור הכללי.')

# שורות כותרת בלבד — גם הן נכללות, בלי לייחס להן כלל עסקי חדש.
headers={6:{12:'המוציא — לחמניות ומציות',16:'סלטים',25:'מנות ראשונות',37:'מנות עיקריות',46:'תוספות חמות',58:'מנות אחרונות / קינוחים'},7:{10:'המוציא — לחמניות ומציות',14:'סלטים',23:'מנות ראשונות',35:'מנות עיקריות',44:'תוספות חמות',56:'מנות אחרונות / קינוחים'}}
