overview=(base/'overview.md').read_text(encoding='utf8')
md=[overview,'\n# פירוט מלא: גיליון אחר גיליון, שורה אחר שורה\n','שמות הגיליונות מוצגים ללא רווח סופי לנוחות הקריאה; במקור חלקם מסתיימים ברווח. כל כתובת תא להלן שייכת לגיליון של אותו פרק. ערכי נוסחה מוצגים בדיוק השמור במקור; שאריות כמו 499.99999999999994 הן תוצאת דיוק מחשב, לא שינוי בכוונת 500. נוסחאות אינן כוללות עיגול אלא אם הוא מופיע במפורש.']
for i,s in enumerate(src['sheets'],1):
    md += [f"\n## {i}. {s['name'].strip()}\n",f"טווח המקור: `{s['dimension']}`. {len(s['rows'])} שורות עם תוכן. {sum(c['formula_attrs'] is not None for r in s['rows'] for c in r['cells'])} נוסחאות."]
    end=int(re.search(r'\d+$',s['dimension']).group())
    blanks=[str(n) for n in range(1,end+1) if n not in notes[i]]
    if blanks: md.append('שורות ללא תוכן/נוסחה בטווח המקור: '+', '.join(blanks)+'. הן רווחי עיצוב, לא נתונים עסקיים שהושמטו.')
    for r in s['rows']:
        meaning,status,action=notes[i][r['row']]
        md += [f"\n### שורה {r['row']}\n",'| תא | תוכן / תוצאה שמורה | נוסחה מקורית |','|---|---|---|']
        for c in r['cells']:
            val=str(c['value']).replace('|','\\|').replace('\n','<br>')
            md.append(f"| {c['ref']} | {val} | "+('`='+c['formula']+'`' if c['formula'] is not None else '—')+' |')
        md += ['','**מה זה ואיך חושב:** '+meaning,'','**מה יש עכשיו:** '+status,'','**מה לממש או לברר:** '+action]
md += ['\n## זיהוי המקור ובקרת כיסוי\n',f"מקור: {src['source']}",f"SHA-256: `{src['sha256']}`",'הושלמו 176/176 שורות תוכן, 545/545 תאי תוכן ונוסחה, 128/128 נוסחאות. אין שורת תוכן ללא הסבר ומיפוי מצב/פעולה. הקובץ המקורי נשאר ללא שינוי.']
