# רינדור דוח טקסט מקומי; לא יצירה או שינוי של חוברת Excel.
def inline(t):
    t=html.escape(t)
    t=re.sub(r'`([^`]+)`',r'<code dir="ltr">\1</code>',t)
    t=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',t)
    return t
body=[]; in_table=False; in_list=False; ids=0
for line in text.splitlines():
    if not line.strip():
        if in_table: body.append('</tbody></table></div>');in_table=False
        if in_list: body.append('</ul>');in_list=False
        continue
    if line.startswith('|'):
        if re.match(r'^\|[-| ]+\|$',line): continue
        cells=line.strip('|').split('|')
        if not in_table: body.append('<div class="table"><table><tbody>');in_table=True
        body.append('<tr>'+''.join('<td>'+inline(c.strip())+'</td>' for c in cells)+'</tr>');continue
    if in_table: body.append('</tbody></table></div>');in_table=False
    if line.startswith('#'):
        n=len(line)-len(line.lstrip('#'));ids+=1
        body.append(f'<h{n} id="part-{ids}">'+inline(line.lstrip('# '))+f'</h{n}>')
    elif line.startswith('- '):
        if not in_list: body.append('<ul>');in_list=True
        body.append('<li>'+inline(line[2:])+'</li>')
    else: body.append('<p>'+inline(line)+'</p>')
if in_table: body.append('</tbody></table></div>')
if in_list: body.append('</ul>')
style='''body{direction:rtl;font:17px/1.75 Arial,sans-serif;margin:0;color:#183239;background:#f3f6f6}main{max-width:1150px;margin:auto;padding:34px;background:white}h1{font-size:30px;color:#13554f}h2{margin-top:50px;border-bottom:3px solid #2e8175;padding-bottom:10px}h3{margin-top:32px;background:#eaf4f1;padding:9px 16px}p{max-width:1050px}table{border-collapse:collapse;width:100%;font-size:15px}td{border:1px solid #d7e3e1;padding:10px;vertical-align:top;overflow-wrap:anywhere}tr:first-child{font-weight:bold;background:#eef3f5}code{font-family:Consolas,monospace;unicode-bidi:isolate;display:inline-block;font-size:14px;overflow-wrap:anywhere;max-width:100%}.table{overflow-x:auto}nav{position:sticky;top:0;background:#163f3b;padding:12px;color:white}nav select,nav input,nav button{padding:8px;margin:4px;font-size:15px;border:0;border-radius:4px}nav input{width:210px}a{color:#145f82}@media print{nav{display:none}main{max-width:none;padding:0}h2,h3{break-after:avoid}tr{break-inside:avoid}body{background:white}}'''
page='<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><title>סקירת האקסל ותוכנית עבודה — PlanMyEvents</title><style>'+style+'</style><nav>סקירת האקסל <select id="jump" aria-label="מעבר לפרק"><option value="">מעבר לפרק…</option></select><button onclick="window.print()">הדפסה / שמירה כ־PDF</button><span>לחיפוש בדוח: Ctrl+F</span></nav><main>'+''.join(body)+'</main><script>const sel=document.getElementById("jump");document.querySelectorAll("h1,h2").forEach(h=>{let o=document.createElement("option");o.value=h.id;o.textContent=h.textContent;sel.append(o)});sel.onchange=()=>{if(sel.value)document.getElementById(sel.value).scrollIntoView()};</script></html>'
